function newId(){if(typeof crypto.randomUUID==='function')return crypto.randomUUID();const a=new Uint8Array(16);crypto.getRandomValues(a);return Array.from(a,x=>x.toString(16).padStart(2,'0')).join('')}
const TASK_KEY='learning-garden-tasks-v1';
const KANBAN_COLORS={'Backlog / Later':'lilac','To do':'butter','In progress':'blue',Blocked:'pink',Done:'sage'};
const TASK_STATUSES=['Backlog / Later','To do','In progress','Blocked','Done'];
let boardTasks=null,taskStorageOK=true,boardFilter='All',boardResource='all';
try{const stored=localStorage.getItem(TASK_KEY);if(stored)boardTasks=JSON.parse(stored)}catch{taskStorageOK=false}
function localDay(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function taskDate(date){if(!date)return 'No date set';return new Date(date+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}
function persistTasks(){try{localStorage.setItem(TASK_KEY,JSON.stringify(boardTasks));taskStorageOK=true}catch{taskStorageOK=false}}
function ensureTasks(){if(!Array.isArray(boardTasks)){boardTasks=[];addRoadmapTasks('devfest',false);persistTasks()}return boardTasks}
function addRoadmapTasks(id,announce=true){if(!Array.isArray(boardTasks))boardTasks=[];const r=records.find(r=>r.id===id&&r.kind==='Roadmap');if(!r)return;let count=0;(r.steps||[]).forEach(step=>{if(boardTasks.some(t=>t.resourceId===id&&t.sourceStep===step.text))return;boardTasks.push({id:newId(),title:step.text,resourceId:id,sourceStep:step.text,status:step.done?'Done':'To do',progress:step.done?100:0,priority:priorityValue(r),startDate:'',dueDate:'',notes:'',createdAt:localDay(),completedAt:'',archived:false});count++});persistTasks();if(announce){render();toast(count?`${count} roadmap steps added to your board`:'These roadmap steps are already on your board')}}
function syncTasksFromRoadmaps(){if(!Array.isArray(boardTasks))return;let changed=false;for(const t of boardTasks){if(!t.sourceStep)continue;const r=records.find(r=>r.id===t.resourceId);const s=r?.steps?.find(s=>s.text===t.sourceStep);if(!s)continue;if(s.done&&t.status!=='Done'){t.status='Done';t.progress=100;t.completedAt=localDay();changed=true}else if(!s.done&&t.status==='Done'){t.status='To do';t.progress=0;t.completedAt='';changed=true}}if(changed)persistTasks()}
function applyTaskToRoadmap(t){if(!t.sourceStep)return;const r=records.find(r=>r.id===t.resourceId);const s=r?.steps?.find(s=>s.text===t.sourceStep);if(!s)return;s.done=t.status==='Done';r.status=r.steps.every(s=>s.done)?'Completed':r.steps.some(s=>s.done)||boardTasks.some(x=>x.resourceId===r.id&&['In progress','Blocked'].includes(x.status))?'In progress':'Planned'}
function taskIsOverdue(t){return !t.archived&&t.status!=='Done'&&!!effectiveTaskDue(t)&&effectiveTaskDue(t)<localDay()}
function taskDueSoon(t){if(!effectiveTaskDue(t)||t.status==='Done'||t.archived)return false;const days=(Date.parse(effectiveTaskDue(t)+'T00:00:00Z')-Date.parse(localDay()+'T00:00:00Z'))/86400000;return days>=0&&days<=7}
function taskCard(t){return `<article class="task-card ${taskIsOverdue(t)?'task-overdue':''}"><div class="task-meta"><span>${esc(PRIORITIES[t.priority]||PRIORITIES[''])}</span>${taskIsOverdue(t)?'<strong>Overdue</strong>':''}</div><h3>${esc(t.title)}</h3><div class="bar"><i style="width:${t.progress}%"></i></div><div class="task-meta"><span>${t.progress}% complete</span></div><label class="sr-only" for="task-status-${esc(t.id)}">Status for ${esc(t.title)}</label><select class="task-status-select" id="task-status-${esc(t.id)}" data-task-status="${esc(t.id)}">${TASK_STATUSES.map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('')}</select><button class="textbtn" data-task-edit="${esc(t.id)}" aria-label="Edit task: ${esc(t.title)}">Edit ↗</button></article>`}
function renderBoard(){ensureTasks();preparePlanning();syncTasksFromRoadmaps();const active=boardTasks.filter(t=>!t.archived&&matchesPlanning(t));let tasks=boardTasks.filter(t=>matchesPlanning(t)&&(boardFilter==='Archived'?t.archived:!t.archived)&&(boardFilter==='Overdue'?taskIsOverdue(t):boardFilter==='Next 7 days'?taskDueSoon(t):true)&&(boardResource==='all'||t.resourceId===boardResource)&&[t.title,t.notes,records.find(r=>r.id===t.resourceId)?.title].join(' ').toLowerCase().includes(query.toLowerCase()));const total=active.length,done=active.filter(t=>t.status==='Done').length,average=total?Math.round(active.reduce((sum,t)=>sum+t.progress,0)/total):0;const r=records.find(r=>r.id==='devfest');$('breadcrumb').textContent='My Action Board';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view==='board'));$('content').innerHTML=`<div class="intro"><div><div class="eyebrow">SHOW UP FOR YOUR GOALS</div><h1>My Action Board</h1><p class="muted">Small commitments. Visible progress. A plan you can follow through on.</p></div><button class="primary" id="addTask">＋ New task</button></div><div class="board-goal"><div><span class="tag">🔥 MAIN GOAL</span><h3>DevFest · 5 December 2026</h3><p>Plan your start dates and deadlines below. ${devfestCountdown()}.</p></div><div><button data-read="devfest">Open roadmap ↗</button></div></div>${renderPlanning()}<div class="stats">${[[done+'/'+total,'Sprint tasks completed'],[average+'%','Sprint progress'],[active.filter(taskIsOverdue).length,'Overdue'],[active.filter(t=>t.status==='Blocked').length,'Blocked']].map(([v,label])=>`<div class="stat"><strong>${v}</strong><small>${label}</small></div>`).join('')}</div><div class="board-tools"><div class="filters" style="margin:0">${['All','Overdue','Next 7 days','Archived'].map(f=>`<button data-board-filter="${f}" class="${boardFilter===f?'selected':''}">${f}</button>`).join('')}</div><select id="boardResource" class="filter-select" aria-label="Filter tasks by resource"><option value="all">All courses & roadmaps</option>${records.filter(r=>boardTasks.some(t=>t.resourceId===r.id)).map(r=>`<option value="${esc(r.id)}" ${boardResource===r.id?'selected':''}>${esc(r.title)}</option>`).join('')}</select><button id="importRoadmap">＋ Add roadmap steps</button></div><details class="status-guide"><summary>What do these statuses mean?</summary><p><strong>Backlog / Later:</strong> Saved for another time. <strong>To do:</strong> Ready to tackle next. <strong>In progress:</strong> You’ve started. <strong>Blocked:</strong> Something is stopping you. <strong>Done:</strong> Finished.</p></details><div class="kanban" aria-label="Task board">${TASK_STATUSES.map((status,i)=>{const group=tasks.filter(t=>t.status===status);return `<section class="kanban-col" style="--column-color:${NOTE_COLORS[KANBAN_COLORS[status]]}"><div class="kanban-heading"><span><i class="status-dot status-${i}"></i>${status}</span><span class="task-count">${group.length}</span></div>${group.map(taskCard).join('')||'<div class="column-empty">A little room to move forward.</div>'}</section>`}).join('')}</div>${!tasks.length?'<p class="muted" style="margin-top:16px">No tasks match these filters. Clear the search or switch to All.</p>':''}<div class="banner">${taskStorageOK&&planningStorageOK?'Tasks, sprints and dates save in this browser.':'Browser storage is unavailable; export a backup to keep your changes.'} Completing a linked roadmap task also updates its checklist. Task deadlines override sprint end dates. Keep each sprint small enough to finish. Overdue labels appear when you open this board; this version does not send notifications.</div><footer><span>${done} completed · ${total-done} still to go · Dates shown in India time</span><span><button class="textbtn" id="export">Export backup ↓</button><button class="textbtn" id="import">Import backup ↑</button></span></footer>`}
function showTask(id){ensureTasks();preparePlanning();const t=boardTasks.find(t=>t.id===id)||{status:'To do',progress:0,priority:'',resourceId:'devfest',sprintId:planning.sprints.some(s=>s.id===boardSprint)?boardSprint:''};$('taskSprint').innerHTML=sprintOptions(t.sprintId||'');$('taskSprint').dataset.manualValue=t.sprintId||'';$('taskAutoSchedule').checked=t.autoSchedule!==false;$('taskId').value=t.id||'';$('taskTitle').value=t.title||'';$('taskStatus').innerHTML=TASK_STATUSES.map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('');$('taskPriority').innerHTML=priorityOptions(t.priority||'');$('taskResource').innerHTML='<option value="">Personal task</option>'+records.filter(r=>canPrioritize(r)).map(r=>`<option value="${esc(r.id)}" ${t.resourceId===r.id?'selected':''}>${esc(r.title)}</option>`).join('');$('taskResource').value=t.resourceId||'';$('taskResource').disabled=!!t.sourceStep;for(const [key,el] of [['progress','taskProgress'],['startDate','taskStart'],['dueDate','taskDue'],['notes','taskNotes']])$(el).value=t[key]??'';$('taskModalTitle').textContent=t.id?'Make your next move':'One small commitment';$('archiveTask').classList.toggle('hidden',!t.id);$('archiveTask').textContent=t.archived?'Restore task':'Archive task';$('taskLinkHelp').textContent=t.sourceStep?'Linked to a roadmap checklist step. Marking this task Done updates that step.':'Link to a course or roadmap for context, or choose Personal task.';$('taskDateError').textContent='';previewTaskDateRoute();$('taskDialog').showModal()}
function setTaskState(t,status){t.status=status;if(status==='Done'){t.progress=100;t.completedAt=t.completedAt||localDay()}else{t.completedAt='';if(status==='To do')t.progress=0;else if(status==='Backlog / Later'){if(t.progress===100)t.progress=0}else if(t.progress===0||t.progress===100)t.progress=25}applyTaskToRoadmap(t);persistTasks();save()}
function validateImportedTasks(value){if(!Array.isArray(value)||value.length>20000)throw Error('Invalid tasks');const isDate=d=>!d||/^\d{4}-\d{2}-\d{2}$/.test(d)&&!Number.isNaN(Date.parse(d+'T00:00:00Z'));return value.map(t=>{if(!t||typeof t.title!=='string'||!t.title.trim()||!TASK_STATUSES.includes(t.status)||!isDate(t.startDate)||!isDate(t.dueDate)||!isDate(t.completedAt))throw Error('Invalid task');return {...t,id:typeof t.id==='string'?t.id:newId(),notes:typeof t.notes==='string'?t.notes:'',resourceId:typeof t.resourceId==='string'?t.resourceId:'',sprintId:typeof t.sprintId==='string'?t.sprintId:'',autoSchedule:t.autoSchedule!==false,sourceStep:typeof t.sourceStep==='string'?t.sourceStep:undefined,priority:Object.hasOwn(PRIORITIES,t.priority)?t.priority:'',progress:t.status==='Done'?100:Math.max(0,Math.min(99,Number(t.progress)||0)),archived:!!t.archived}})}
function setupBoard(){document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='addTask')showTask();if(b.dataset.taskEdit)showTask(b.dataset.taskEdit);if(b.dataset.boardFilter){boardFilter=b.dataset.boardFilter;render()}if(b.id==='closeTask'||b.id==='cancelTask')$('taskDialog').close();if(b.id==='archiveTask'){const t=boardTasks.find(t=>t.id===$('taskId').value);t.archived=!t.archived;persistTasks();$('taskDialog').close();render();toast(t.archived?'Task archived. Find it in Archived.':'Task restored')}if(b.id==='importRoadmap'){$('roadmapImportSelect').innerHTML=records.filter(r=>r.kind==='Roadmap').map(r=>`<option value="${esc(r.id)}">${esc(r.title)}</option>`).join('');$('roadmapImportDialog').showModal()}if(b.id==='cancelRoadmapImport')$('roadmapImportDialog').close();if(b.id==='confirmRoadmapImport'){addRoadmapTasks($('roadmapImportSelect').value);$('roadmapImportDialog').close()}});document.addEventListener('change',e=>{if(e.target.id==='boardResource'){boardResource=e.target.value;render()}if(e.target.dataset.taskStatus){const t=boardTasks.find(t=>t.id===e.target.dataset.taskStatus);setTaskState(t,e.target.value);toast('Task status updated')}if(e.target.id==='taskStatus'){if(e.target.value==='Done')$('taskProgress').value=100;else if(e.target.value==='To do')$('taskProgress').value=0;else if(e.target.value==='Backlog / Later'){if(Number($('taskProgress').value)===100)$('taskProgress').value=0}else if([0,100].includes(Number($('taskProgress').value)))$('taskProgress').value=25}});$('taskForm').addEventListener('submit',e=>{e.preventDefault();if(!$('taskTitle').value.trim()){$('taskDateError').textContent='Give this task a short title.';return}const startDate=$('taskStart').value,dueDate=$('taskDue').value;if(startDate&&dueDate&&startDate>dueDate){$('taskDateError').textContent='The deadline must be on or after the start date.';return}let t=boardTasks.find(t=>t.id===$('taskId').value);if(!t){t={id:newId(),createdAt:localDay(),archived:false};boardTasks.push(t)}t.title=$('taskTitle').value.trim();t.status=$('taskStatus').value;t.progress=Number($('taskProgress').value);if(t.progress===100)t.status='Done';else if(t.status==='Done')t.progress=100;else if(t.status==='To do'&&t.progress>0)t.status='In progress';t.priority=$('taskPriority').value;t.startDate=startDate;t.dueDate=dueDate;t.notes=$('taskNotes').value.trim();t.sprintId=$('taskSprint').value;t.autoSchedule=$('taskAutoSchedule').checked;const scheduledSprint=followDatedTask(t);if(!t.sourceStep)t.resourceId=$('taskResource').value;t.completedAt=t.status==='Done'?(t.completedAt||localDay()):'';applyTaskToRoadmap(t);persistTasks();save();$('taskDialog').close();toast(scheduledSprint?'Task saved in '+monthLabel(scheduledSprint.month)+' · '+scheduledSprint.name:'Task saved')})}
